package cz.artefaktlab.spacemap;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.provider.DocumentsContract;import android.database.Cursor;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 static final int PICK=41; ExecutorService worker=Executors.newSingleThreadExecutor(); Uri tree; Node root,current,selected; boolean classic=true; LinearLayout panel; TextView status; TreeMapView view; Deque<Node> history=new ArrayDeque<>();
 static class Node { Uri uri;String name,mime;boolean folder;long bytes;ArrayList<Node> children=new ArrayList<>();Node(Uri u,String n,String m,boolean f,long b){uri=u;name=n;mime=m;folder=f;bytes=b;}}
 public void onCreate(Bundle b){super.onCreate(b);panel=new LinearLayout(this);panel.setOrientation(1);panel.setBackgroundColor(0xff101820);setContentView(panel);LinearLayout tools=new LinearLayout(this);tools.setOrientation(LinearLayout.VERTICAL);panel.addView(tools);add(tools,"Vybrat",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,PICK);});add(tools,"Skenovat",()->scan());add(tools,"Zpět",()->{if(!history.isEmpty()){current=history.pop();refresh();}});add(tools,"Classic / Modern",()->{classic=!classic;refresh();});add(tools,"Soubor",()->menu());add(tools,"CPU-Q",()->{Intent i=getPackageManager().getLaunchIntentForPackage("cz.artefaktlab.cpuq");if(i!=null)startActivity(i);else Toast.makeText(this,"CPU-Q není dostupné pod očekávaným ID balíčku",Toast.LENGTH_LONG).show();});status=new TextView(this);status.setTextColor(-1);status.setPadding(12,12,12,12);status.setText("Vyber složku k analýze");panel.addView(status);view=new TreeMapView();panel.addView(view,new LinearLayout.LayoutParams(-1,0,1));}
 void add(LinearLayout p,String t,Runnable r){LinearLayout line;if(p.getChildCount()==0||((LinearLayout)p.getChildAt(p.getChildCount()-1)).getChildCount()>=3){line=new LinearLayout(this);line.setOrientation(LinearLayout.HORIZONTAL);p.addView(line,new LinearLayout.LayoutParams(-1,dp(48)));}else line=(LinearLayout)p.getChildAt(p.getChildCount()-1);Button b=new Button(this);b.setText(t);b.setAllCaps(false);b.setTextSize(11);b.setSingleLine(true);b.setEllipsize(android.text.TextUtils.TruncateAt.END);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(2),0,dp(2),0);b.setOnClickListener(v->r.run());line.addView(b,new LinearLayout.LayoutParams(0,-1,1));} int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+0.5f);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK&&result==RESULT_OK&&data!=null){tree=data.getData();try{getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(Exception ignored){}scan();}}
 void scan(){if(tree==null)return;status.setText("Skenování…");worker.execute(()->{try{Uri u=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));Node n=load(u,0,new int[]{0});runOnUiThread(()->{root=n;current=n;selected=null;history.clear();refresh();});}catch(Exception e){error(e);}});}
 Node load(Uri uri,int depth,int[] count)throws Exception{String[] cols={DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE};try(Cursor c=getContentResolver().query(uri,cols,null,null,null)){if(c==null||!c.moveToFirst())throw new Exception("Nelze číst položku");String name=c.getString(0),mime=c.getString(1);boolean dir=DocumentsContract.Document.MIME_TYPE_DIR.equals(mime);Node n=new Node(uri,name,mime,dir,c.isNull(2)?0:Math.max(0,c.getLong(2)));if(dir&&depth<32&&count[0]<100000){Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getDocumentId(uri));try(Cursor rows=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID},null,null,null)){if(rows!=null)while(rows.moveToNext()&&count[0]<100000){count[0]++;try{n.children.add(load(DocumentsContract.buildDocumentUriUsingTree(tree,rows.getString(0)),depth+1,count));}catch(Exception ignored){}}}n.bytes=0;for(Node ch:n.children)n.bytes+=ch.bytes;}return n;}}
 void refresh(){if(current!=null)status.setText((classic?"CLASSIC":"MODERN")+" • "+current.name+" • "+current.bytes+" B • "+current.children.size()+" položek");view.invalidate();}
 void error(Exception e){runOnUiThread(()->new AlertDialog.Builder(this).setMessage(String.valueOf(e.getMessage())).setPositiveButton("OK",null).show());}
 void enter(Node n){if(n.folder){history.push(current);current=n;selected=null;refresh();}else{try{Intent i=new Intent(Intent.ACTION_VIEW).setDataAndType(n.uri,n.mime).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Otevřít"));}catch(Exception e){error(e);}}}
 void menu(){if(selected==null){Toast.makeText(this,"Vyber soubor nebo složku",Toast.LENGTH_SHORT).show();return;}Node n=selected;new AlertDialog.Builder(this).setTitle(n.name).setItems(new String[]{"Otevřít","Přejmenovat","Odstranit"},(d,w)->{if(w==0)enter(n);if(w==1){EditText input=new EditText(this);input.setText(n.name);new AlertDialog.Builder(this).setTitle("Přejmenovat").setView(input).setNegativeButton("Zrušit",null).setPositiveButton("Uložit",(a,b)->worker.execute(()->{try{DocumentsContract.renameDocument(getContentResolver(),n.uri,input.getText().toString());scan();}catch(Exception e){error(e);}})).show();}if(w==2)new AlertDialog.Builder(this).setMessage("Odstranit "+n.name+"?").setNegativeButton("Zrušit",null).setPositiveButton("Odstranit",(a,b)->worker.execute(()->{try{DocumentsContract.deleteDocument(getContentResolver(),n.uri);scan();}catch(Exception e){error(e);}})).show();}).show();}
 class TreeMapView extends View{Paint p=new Paint(3);ArrayList<Hit> hits=new ArrayList<>();class Hit{RectF r;Node n;Hit(RectF a,Node b){r=a;n=b;}}TreeMapView(){super(MainActivity.this);}protected void onDraw(Canvas c){c.drawColor(classic?0xff050505:0xff101820);hits.clear();if(current!=null)draw(c,current,new RectF(4,4,getWidth()-4,getHeight()-4),0);}
 void draw(Canvas c,Node parent,RectF area,int depth){if(depth>5||area.width()<5||area.height()<5)return;ArrayList<Node> nodes=new ArrayList<>(parent.children);nodes.sort((a,b)->Long.compare(b.bytes,a.bytes));double remaining=0;for(Node n:nodes)remaining+=Math.max(1,n.bytes);float x=area.left,y=area.top,w=area.width(),h=area.height();for(Node n:nodes){double fraction=Math.max(1,n.bytes)/remaining;RectF r;if(w>=h){float sw=(float)(w*fraction);r=new RectF(x,y,x+sw,y+h);x+=sw;w-=sw;}else{float sh=(float)(h*fraction);r=new RectF(x,y,x+w,y+sh);y+=sh;h-=sh;}remaining-=Math.max(1,n.bytes);int[] colors={0xffe8bc37,0xff4cb66d,0xff4b9ed4,0xffcf684f,0xff9879cf};p.setColor(classic?colors[(n.name.hashCode()&0x7fffffff)%colors.length]:Color.HSVToColor(new float[]{(n.name.hashCode()&0x7fffffff)%360,.52f,.74f}));c.drawRect(r,p);p.setColor(0xff101820);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(classic?1:3);c.drawRect(r,p);p.setStyle(Paint.Style.FILL);hits.add(new Hit(r,n));if(r.width()>65&&r.height()>28){p.setColor(-1);p.setTextSize(classic?12:15);c.save();c.clipRect(r);c.drawText(n.name,r.left+4,r.top+17,p);c.restore();}if(n.folder&&r.width()>100&&r.height()>75)draw(c,n,new RectF(r.left+3,r.top+26,r.right-3,r.bottom-3),depth+1);}}
 public boolean onTouchEvent(MotionEvent e){if(e.getAction()==MotionEvent.ACTION_UP){for(int i=hits.size()-1;i>=0;i--){Hit h=hits.get(i);if(h.r.contains(e.getX(),e.getY())){selected=h.n;if(selected.folder)enter(selected);else menu();return true;}}}return true;}}
 protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}